    // 통화 요약 진단 및 복구 (수동 트리거)
    window.diagnoseCallDelay = function() {
        const spinner = document.getElementById('diagnose-spinner');
        spinner.style.display = 'inline';

        // Firebase Cloud Function (HTTPS Callable) 호출
        const diagnoseCallStatus = window.firebase.functions("asia-northeast3").httpsCallable('diagnoseCallStatus');

        diagnoseCallStatus().then(result => {
            spinner.style.display = 'none';
            const res = result.data;

            if (res.status === 'NOT_UPLOADED') {
                Swal.fire({
                    icon: 'error',
                    title: '스마트폰 업로드 실패',
                    html: `클라우드에 통화 녹음 파일이 아예 도착하지 않았습니다.<br><br>순간적인 인터넷 끊김이나 안드로이드 절전 기능이 원인일 수 있습니다.<br><br><b>[복구 방법]</b><br>스마트폰에서 MacroDroid 앱을 열고 해당 'Call Ended' 매크로를 눌러 <b>'매크로 테스트(Test Macro)'를 수동으로 한 번 실행</b>하시면 최신 파일이 다시 전송됩니다.`,
                    confirmButtonText: '확인'
                });
            } else if (res.status === 'RETRYING') {
                Swal.fire({
                    icon: 'warning',
                    title: '클라우드 에러 (재시도 중)',
                    text: 'AI 분석 중 오류가 있었습니다. 지금 클라우드에서 자동으로 재시도를 시작했습니다. 약 30초 후 확인해주세요.',
                    confirmButtonText: '알겠습니다'
                });
            } else if (res.status === 'PROCESSING') {
                Swal.fire({
                    icon: 'info',
                    title: '서버 처리 중',
                    text: '현재 파일이 서버에 도착하여 딥러닝 분석이 진행 중입니다. 잠시만 기다려주세요.',
                    confirmButtonText: '확인'
                });
            } else if (res.status === 'DONE') {
                Swal.fire({
                    icon: 'success',
                    title: '분석 완료',
                    text: '이미 분석이 정상적으로 완료되어 데이터베이스에 저장되었습니다. 목록을 확인해주세요.',
                    confirmButtonText: '확인'
                });
            } else {
                Swal.fire({
                    icon: 'question',
                    title: '진단 상태 알 수 없음',
                    text: res.message || '알 수 없는 오류입니다.',
                    confirmButtonText: '닫기'
                });
            }
        }).catch(err => {
            spinner.style.display = 'none';
            console.error(err);
            Swal.fire({
                icon: 'error',
                title: '진단 중 에러 발생',
                text: err.message || '서버와 통신 중 문제가 발생했습니다.',
                confirmButtonText: '닫기'
            });
        });
    };
</script>
